  const quotes = collections.flatMap(({ author, path, entries }) => entries.map(([text, source]) => Object.freeze({
    text, author, source, url: `https://zh.wikisource.org/zh-hans/${encodeURI(path)}`
  })));

  function hourlyOrder(cycle) {
    const order = quotes.map((_, index) => index);
    let seed = (cycle ^ 0x9e3779b9) >>> 0;
    for (let index = order.length - 1; index > 0; index -= 1) {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      const swapIndex = seed % (index + 1);
      [order[index], order[swapIndex]] = [order[swapIndex], order[index]];
    }
    return order;
  }

  function forHour(hour) {
    if (!Number.isFinite(hour) || !quotes.length) return null;
    const cycle = Math.floor(hour / quotes.length);
    const slot = ((Math.floor(hour) % quotes.length) + quotes.length) % quotes.length;
    const order = hourlyOrder(cycle);
    // Swapping the first two leaves the last unchanged and avoids boundary repeats.
    if (quotes.length > 2 && order[0] === hourlyOrder(cycle - 1).at(-1)) {
      [order[0], order[1]] = [order[1], order[0]];
    }
    return quotes[order[slot]];
  }

  window.REVIEW_INSPIRATION = Object.freeze({ quotes: Object.freeze(quotes), forHour });
